import{_ as d,o as e,c as a,a6 as n}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"二进制分帧层","description":"9 字节帧头的每个比特、十种帧类型与标志位的精确语义。","frontmatter":{"title":"二进制分帧层","description":"9 字节帧头的每个比特、十种帧类型与标志位的精确语义。","source":"https://daiw.org/manual/http2-3/h2-framing"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-framing.md","filePath":"manual/computer-programming/http2-3/h2-framing.md"}'),o={name:"manual/computer-programming/http2-3/h2-framing.md"};function s(r,t,c,p,l,i){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="二进制分帧层" tabindex="-1">二进制分帧层 <a class="header-anchor" href="#二进制分帧层" aria-label="Permalink to &quot;二进制分帧层&quot;">​</a></h1><p>9 字节帧头的每个比特、十种帧类型与标志位的精确语义。</p><h2 id="帧头格式" tabindex="-1">帧头格式 <a class="header-anchor" href="#帧头格式" aria-label="Permalink to &quot;帧头格式&quot;">​</a></h2><p>所有 h2 帧共用 <strong>9 字节</strong>定长头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------+</span></span>
<span class="line"><span>|                 Length (24)                   |</span></span>
<span class="line"><span>+---------------+---------------+---------------+</span></span>
<span class="line"><span>|   Type (8)    |   Flags (8)   |</span></span>
<span class="line"><span>+-+-------------+---------------+-------------------------------+</span></span>
<span class="line"><span>|R|                 Stream Identifier (31)                      |</span></span>
<span class="line"><span>+=+=============================================================+</span></span>
<span class="line"><span>|                   Frame Payload (0...)                      ...</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>逐字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>位宽</th><th>说明</th></tr></thead><tbody><tr><td>Length</td><td>24</td><td>载荷长度（<strong>不含</strong>这 9 字节头）。默认上限 <strong>16384</strong>（2^14），由 <code>SETTINGS_MAX_FRAME_SIZE</code> 调整，最大 16777215</td></tr><tr><td>Type</td><td>8</td><td>帧类型。未知类型 <strong>MUST</strong> 被忽略而非报错——这是协议的扩展点</td></tr><tr><td>Flags</td><td>8</td><td>类型专属标志位，未定义位 <strong>MUST</strong> 置 0 且被忽略</td></tr><tr><td>R</td><td>1</td><td>保留位，<strong>MUST</strong> 置 0，接收时忽略</td></tr><tr><td>Stream Identifier</td><td>31</td><td>流 ID。<strong>0 表示连接级</strong>，非零表示某个流</td></tr></tbody></table><p>关键改进：<strong>长度前置且定长</strong>。1.1 必须扫描字节找 CRLF、再按 <code>Content-Length</code> 或分块解析——正是这种「靠扫描定界」造成了<a href="/Front2Full/manual/computer-programming/http11/message-body-length">请求走私</a>。h2 直接读 24 位长度，边界<strong>无歧义</strong>，走私类攻击在协议层被消除。</p><h2 id="十种帧类型" tabindex="-1">十种帧类型 <a class="header-anchor" href="#十种帧类型" aria-label="Permalink to &quot;十种帧类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>名称</th><th>流 ID</th><th>作用</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>DATA</code></td><td>非零</td><td>消息体</td></tr><tr><td><code>0x01</code></td><td><code>HEADERS</code></td><td>非零</td><td>字段块，开启流</td></tr><tr><td><code>0x02</code></td><td><code>PRIORITY</code></td><td>非零</td><td>优先级（<strong>已废弃</strong>）</td></tr><tr><td><code>0x03</code></td><td><code>RST_STREAM</code></td><td>非零</td><td>立即终止单个流</td></tr><tr><td><code>0x04</code></td><td><code>SETTINGS</code></td><td><strong>0</strong></td><td>连接参数协商</td></tr><tr><td><code>0x05</code></td><td><code>PUSH_PROMISE</code></td><td>非零</td><td>服务端推送预告（<strong>已废弃</strong>）</td></tr><tr><td><code>0x06</code></td><td><code>PING</code></td><td><strong>0</strong></td><td>保活与 RTT 测量</td></tr><tr><td><code>0x07</code></td><td><code>GOAWAY</code></td><td><strong>0</strong></td><td>优雅关闭连接</td></tr><tr><td><code>0x08</code></td><td><code>WINDOW_UPDATE</code></td><td>0 或非零</td><td>流量控制窗口增量</td></tr><tr><td><code>0x09</code></td><td><code>CONTINUATION</code></td><td>非零</td><td>字段块续帧</td></tr></tbody></table><p>流 ID 用错（如 <code>SETTINGS</code> 带非零流 ID）是 <code>PROTOCOL_ERROR</code>，<strong>必须</strong>关闭整个连接。</p><h2 id="data" tabindex="-1">DATA <a class="header-anchor" href="#data" aria-label="Permalink to &quot;DATA&quot;">​</a></h2><p>承载消息体，等价于 1.1 的 message-body。</p><p>标志位：</p><table tabindex="0"><thead><tr><th>标志</th><th>值</th><th>语义</th></tr></thead><tbody><tr><td><code>END_STREAM</code></td><td><code>0x01</code></td><td>本帧是该流方向上的最后一帧</td></tr><tr><td><code>PADDED</code></td><td><code>0x08</code></td><td>载荷带填充</td></tr></tbody></table><ul><li><strong>受<a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">流量控制</a>约束</strong>——是唯一受控的帧类型。</li><li>填充用于混淆真实长度以抵御流量分析（BREACH 类）；Pad Length 字段占 1 字节，填充内容 <strong>MUST</strong> 全零且接收方 <strong>MUST NOT</strong> 解释。</li><li>填充长度大于剩余载荷 → <code>PROTOCOL_ERROR</code>。</li></ul><h2 id="headers" tabindex="-1">HEADERS <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;HEADERS&quot;">​</a></h2><p>承载 HPACK 编码后的字段块，同时<strong>开启一个流</strong>。</p><p>标志位：</p><table tabindex="0"><thead><tr><th>标志</th><th>值</th><th>语义</th></tr></thead><tbody><tr><td><code>END_STREAM</code></td><td><code>0x01</code></td><td>该流方向到此结束（如无体的 GET）</td></tr><tr><td><code>END_HEADERS</code></td><td><code>0x04</code></td><td>字段块到此完整，无后续 <code>CONTINUATION</code></td></tr><tr><td><code>PADDED</code></td><td><code>0x08</code></td><td>带填充</td></tr><tr><td><code>PRIORITY</code></td><td><code>0x20</code></td><td>载荷含优先级信息（<strong>已废弃</strong>）</td></tr></tbody></table><p>注意 <code>END_STREAM</code> 与 <code>END_HEADERS</code> 是<strong>两个独立</strong>标志：一个无请求体的 GET 会同时置位；一个带体的 POST 只置 <code>END_HEADERS</code>，体由后续 <code>DATA</code> 帧发送并在最后一帧置 <code>END_STREAM</code>。</p><h2 id="continuation" tabindex="-1">CONTINUATION <a class="header-anchor" href="#continuation" aria-label="Permalink to &quot;CONTINUATION&quot;">​</a></h2><p>字段块超过 <code>MAX_FRAME_SIZE</code> 时的续帧。</p><p><strong>最严格的排序约束</strong>：<code>HEADERS</code>/<code>PUSH_PROMISE</code> 与其后续 <code>CONTINUATION</code> 之间 <strong>MUST NOT</strong> 插入任何其他帧（哪怕是其他流的帧）。违反即 <code>PROTOCOL_ERROR</code>。</p><p>原因：HPACK 动态表是<strong>有状态且顺序相关</strong>的，字段块必须作为不可分割的整体解码。这也意味着<strong>巨大的头部会短暂阻塞整条连接</strong>——即所谓 CONTINUATION Flood 攻击面。</p><h2 id="rst-stream" tabindex="-1">RST_STREAM <a class="header-anchor" href="#rst-stream" aria-label="Permalink to &quot;RST_STREAM&quot;">​</a></h2><p>载荷是 4 字节<a href="/Front2Full/manual/computer-programming/http2-3/h2-connection">错误码</a>，立即终止<strong>单个流</strong>，不影响连接。</p><p>这是 1.1 完全没有的能力：1.1 想取消一个进行中的请求，只能关掉整条 TCP 连接。</p><p>代价：<code>RST_STREAM</code> 极廉价（客户端发一帧即可让服务端丢弃工作），2023 年的 <strong>HTTP/2 Rapid Reset</strong>（CVE-2023-44487）正是利用「快速开流再立即重置」绕过 <code>MAX_CONCURRENT_STREAMS</code> 限制发起 DDoS。缓解手段是限制单位时间内的重置速率。</p><h2 id="ping" tabindex="-1">PING <a class="header-anchor" href="#ping" aria-label="Permalink to &quot;PING&quot;">​</a></h2><p>8 字节不透明载荷，流 ID 必须为 0。</p><ul><li>收到未置 <code>ACK</code> 的 <code>PING</code> → <strong>MUST</strong> 原样回送并置 <code>ACK</code>（<code>0x01</code>）。</li><li>载荷长度不等于 8 → <code>FRAME_SIZE_ERROR</code>。</li><li>用于测量 RTT 与探测连接存活，优先级应高于其他帧。</li></ul><h2 id="帧与-1-1-的映射" tabindex="-1">帧与 1.1 的映射 <a class="header-anchor" href="#帧与-1-1-的映射" aria-label="Permalink to &quot;帧与 1.1 的映射&quot;">​</a></h2><p>一次完整的 h2 请求/响应：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → HEADERS[END_HEADERS]              请求头</span></span>
<span class="line"><span>客户端 → DATA                              请求体</span></span>
<span class="line"><span>客户端 → DATA[END_STREAM]                  请求体末尾</span></span>
<span class="line"><span>服务端 → HEADERS[END_HEADERS]              响应头(含 :status)</span></span>
<span class="line"><span>服务端 → DATA                              响应体</span></span>
<span class="line"><span>服务端 → DATA[END_STREAM]                  响应体末尾</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>对照 1.1：<code>HEADERS</code> ≈ 起始行 + 字段行，<code>DATA</code> ≈ message-body，<code>END_STREAM</code> ≈ <code>Content-Length</code> 耗尽或 last-chunk。</p><p><strong>trailer 字段</strong>在 h2 中表示为：<code>END_STREAM</code> 之前再发一个 <code>HEADERS</code> 帧（且该帧置 <code>END_STREAM</code>）——比 1.1 的<a href="/Front2Full/manual/computer-programming/http11/field-syntax">分块 trailer 区</a>干净得多。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-streams">流与多路复用</a>。</p>`,38)])])}const m=d(o,[["render",s]]);export{g as __pageData,m as default};
